func:
// Store RPC info if present
if (msg.rpcResponseTopic) {
    flow.set("gds_rpc_response_topic", msg.rpcResponseTopic);
}
if (msg.isRpcRequest) {
    flow.set("gds_is_rpc_request", true);
}

// Send to all 4 parallel reads
return [msg, msg, msg, msg];

// Generator historical runtime (32-bit)
// 512: Low word
// 513: High word
// Unit: 0.1h

msg.baseAddr = 512;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 512,
    quantity: 2
};
return msg;

// Daily energy and runtime
// 536: Today Gen Energy (0.1kWh)
// 537-538: Total Gen Energy (0.1kWh, 32-bit)
// 539: Daily Runtime (0.1h)

msg.baseAddr = 536;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 536,
    quantity: 4
};
return msg;

// Grid-side frequency (shared with grid)
// 609: Frequency (0.01Hz)

msg.baseAddr = 609;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 609,
    quantity: 1
};
return msg;

// 3-phase voltage and power
// 661-663: Phase voltage A, B, C (0.1V)
// 664-667: Phase power A, B, C, Total (low word, 1W, S32)
// 668-671: Phase power A, B, C, Total (high word, 1W, S32)

msg.baseAddr = 661;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 661,
    quantity: 11
};
return msg;

// Build GeneratorDeviceState from 4 parallel Modbus reads.

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("GeneratorDeviceState: missing base address");
    return null;
}

// Helper: combine two 16-bit words to 32-bit unsigned
function u32(low, high) {
    return ((high & 0xFFFF) << 16) | (low & 0xFFFF);
}

// Helper: combine two 16-bit words to 32-bit signed
function s32(low, high) {
    const val = u32(low, high);
    return (val & 0x80000000) ? val - 0x100000000 : val;
}

// ---- Store partials ----

// Runtime 512-513
if (baseAddr === 512) {
    const runtimeLow = data[0] || 0;   // 512
    const runtimeHigh = data[1] || 0;  // 513
    const totalRuntime = u32(runtimeLow, runtimeHigh) * 0.1;

    flow.set("gds_part_runtime", {
        accumulatedRunTimeHours: Math.round(totalRuntime * 10) / 10
    });
}

// Daily 536-539
else if (baseAddr === 536) {
    const todayEnergy = data[0] || 0;    // 536
    const totalLow = data[1] || 0;       // 537
    const totalHigh = data[2] || 0;      // 538
    const dailyRuntime = data[3] || 0;   // 539

    const totalEnergy = u32(totalLow, totalHigh) * 0.1;

    flow.set("gds_part_daily", {
        todayGenEnergyKWh: Math.round((todayEnergy * 0.1) * 100) / 100,
        totalGenEnergyKWh: Math.round(totalEnergy * 100) / 100,
        dailyRunTimeHours: Math.round((dailyRuntime * 0.1) * 10) / 10
    });
}

// Frequency 609
else if (baseAddr === 609) {
    const freqRaw = data[0] || 0;  // 0.01Hz

    flow.set("gds_part_freq", {
        genFrequencyHz: Math.round((freqRaw * 0.01) * 100) / 100
    });
}

// Voltage/Power 661-671
else if (baseAddr === 661) {
    const voltageA = data[0] || 0;   // 661: Phase A voltage (0.1V)
    const voltageB = data[1] || 0;   // 662: Phase B voltage (0.1V)
    const voltageC = data[2] || 0;   // 663: Phase C voltage (0.1V)

    // Power low words (S32)
    const powerALow = data[3] || 0;  // 664
    const powerBLow = data[4] || 0;  // 665
    const powerCLow = data[5] || 0;  // 666
    const powerTotalLow = data[6] || 0;  // 667

    // Power high words (S32)
    const powerAHigh = data[7] || 0;  // 668
    const powerBHigh = data[8] || 0;  // 669
    const powerCHigh = data[9] || 0;  // 670
    const powerTotalHigh = data[10] || 0;  // 671

    // Combine to 32-bit signed
    const powerA = s32(powerALow, powerAHigh);
    const powerB = s32(powerBLow, powerBHigh);
    const powerC = s32(powerCLow, powerCHigh);
    const powerTotal = s32(powerTotalLow, powerTotalHigh);

    flow.set("gds_part_voltage_power", {
        phaseAVoltageV: Math.round((voltageA * 0.1) * 10) / 10,
        phaseBVoltageV: Math.round((voltageB * 0.1) * 10) / 10,
        phaseCVoltageV: Math.round((voltageC * 0.1) * 10) / 10,
        phaseAPowerW: powerA,
        phaseBPowerW: powerB,
        phaseCPowerW: powerC,
        totalPowerW: powerTotal
    });
}
else {
    return null;
}

// ---- Try to assemble ----

const runtimePart = flow.get("gds_part_runtime");
const dailyPart = flow.get("gds_part_daily");
const freqPart = flow.get("gds_part_freq");
const voltagePowerPart = flow.get("gds_part_voltage_power");

if (!runtimePart || !dailyPart || !freqPart || !voltagePowerPart) {
    return null;  // Wait for all 4 parts
}

const deviceId = msg.deviceId
    || global.get("DEVICE_ID")
    || env.get("DEVICE_ID")
    || "EC100-DEV-001";

const state = {
    kind: "GeneratorDeviceState",
    timestampUtc: new Date().toISOString(),
    version: 1,
    DeviceId: deviceId,

    genVoltage: {
        phaseAVoltageV: voltagePowerPart.phaseAVoltageV,
        phaseBVoltageV: voltagePowerPart.phaseBVoltageV,
        phaseCVoltageV: voltagePowerPart.phaseCVoltageV
    },

    genFrequencyHz: freqPart.genFrequencyHz,

    genPower: {
        phaseAPowerW: voltagePowerPart.phaseAPowerW,
        phaseBPowerW: voltagePowerPart.phaseBPowerW,
        phaseCPowerW: voltagePowerPart.phaseCPowerW,
        totalPowerW: voltagePowerPart.totalPowerW
    },

    smartLoadActivePowerW: voltagePowerPart.totalPowerW,

    todayGenEnergyKWh: dailyPart.todayGenEnergyKWh,
    dailyRunTimeHours: dailyPart.dailyRunTimeHours,

    totalGenEnergyKWh: dailyPart.totalGenEnergyKWh,
    accumulatedRunTimeHours: runtimePart.accumulatedRunTimeHours
};

// Clear partials
flow.set("gds_part_runtime", null);
flow.set("gds_part_daily", null);
flow.set("gds_part_freq", null);
flow.set("gds_part_voltage_power", null);

// Get RPC info
const rpcResponseTopic = flow.get("gds_rpc_response_topic");
const isRpcRequest = flow.get("gds_is_rpc_request");
flow.set("gds_rpc_response_topic", null);
flow.set("gds_is_rpc_request", null);

flow.set("generatorDeviceStateSnapshot", state);

msg.payload = state;
msg.state = state;
msg.rpcResponseTopic = rpcResponseTopic;
msg.isRpcRequest = isRpcRequest;

return msg;

// Check if generator is active or if this is an RPC request
// Only send to ThingsBoard telemetry if:
// 1. Generator has power (any phase != 0)
// 2. OR Generator has voltage (any phase > 0)
// 3. OR Generator has frequency (genFrequencyHz > 0)
// 4. OR This is an RPC request (always respond)

const state = msg.payload;
const isRpcRequest = msg.isRpcRequest === true;

const hasPower = state.genPower.phaseAPowerW !== 0 
    || state.genPower.phaseBPowerW !== 0 
    || state.genPower.phaseCPowerW !== 0;

const hasVoltage = state.genVoltage.phaseAVoltageV > 0 
    || state.genVoltage.phaseBVoltageV > 0 
    || state.genVoltage.phaseCVoltageV > 0;

const hasFrequency = state.genFrequencyHz > 0;
const isGeneratorActive = hasPower || hasVoltage || hasFrequency;

// RPC requests always get a response
if (isRpcRequest) {
    msg.topic = msg.rpcResponseTopic;
    node.status({ 
        fill: "blue", 
        shape: "dot", 
        text: `RPC response - ${state.genPower.totalPowerW}W` 
    });
    return [msg, msg];  // Send to both telemetry and RPC response
}

// Periodic poll - only send if generator is active
if (!isGeneratorActive) {
    // Check if we need to send "generator stopped" once
    const previousWasActive = flow.get("gds_previous_was_active") || false;

    if (previousWasActive) {
        // Send one "stopped" message
        flow.set("gds_previous_was_active", false);
        node.status({ fill: "grey", shape: "dot", text: "Stopped - sent" });
        return [msg, null];  // Send to telemetry only
    } else {
        // Already sent stopped, don't spam
        node.status({ fill: "grey", shape: "ring", text: "Inactive - skipped" });
        return [null, null];
    }
}

// Generator is active - send it
flow.set("gds_previous_was_active", true);

node.status({ 
    fill: "green", 
    shape: "dot", 
    text: `Active - ${state.genPower.totalPowerW}W` 
});

return [msg, null];  // Send to telemetry only
